// Probe arm CONTROL: a direct serialize onto a target whose overlay is held fails, so the lock still reproduces here.
[Fact]
public void ADirectSerializeOntoAMappedTargetFails()
{
    var key = new ModKey("HcWriteLockGuard", ModType.Plugin);
    var target = TwoKeywordPatch(key, out _);
    var ov = SkyrimMod.CreateFromBinaryOverlay(target, SkyrimRelease.SkyrimSE);
    try
    {
        _ = ov.EnumerateMajorRecords().FirstOrDefault();
        var patch = new SkyrimMod(key, SkyrimRelease.SkyrimSE);
        patch.Keywords.AddNew().EditorID = "HcWriteLockGuard_Ctrl";

        Assert.ThrowsAny<Exception>(() => patch.BeginWrite.ToPath(target).WithLoadOrder(new ISkyrimModGetter[] { ov }).Write());
    }
    finally { (ov as IDisposable)?.Dispose(); }
}

/// <summary><c>Assert.Throws</c> is what states no quietly-empty plugin came back.</summary>
[Fact]
public void WhileHeldTheEngineReadFaultsLoudly_AndReturnsNoQuietlyEmptyPlugin()
{
    using var world = new LockWorld();
    using var hold = HeldOpen.Hold(world.PluginPath);

    var ex = Assert.Throws<IOException>(() => Read(world.PluginPath));

    // ERROR_SHARING_VIOLATION. The BCL composes the message, so a substring of it would pin .NET.
    Assert.Equal(32, ex.HResult & 0xFFFF);

    hold.Dispose();
    world.AssertNoHandlesLeft();
}

/// <summary>A real filename is untouched by that gate: it reaches the tool body, which judges the lane.</summary>
[Fact]
public void AFilenameInPlaceIsNotRefusedByTheBooleanGate()
{
    var r = _s.Call(ToolNames.Apply, """{"ops":[],"in_place":"NoSuchPlugin.esp"}""");

    Assert.DoesNotContain("names no file", r.Text, StringComparison.Ordinal);
    Assert.True(r.BodyRan, r.Describe());
}
